#pragma once
template<class Check> void interceptionChecks(Check check){
 using namespace ff3Assist;ff3Play::Scene s;s.valid=s.focused=s.grounded=true;s.menu=s.typing=false;s.pid=1;s.model=2;s.own=3;s.player=4;s.at=10;s.groundY=0;s.head={0,5,0};s.rootPosition={0,3.5,0};s.standingRootHeight=3.5;s.standingHeadHeight=5;s.speed=22;s.jumpVelocity=50;s.worldGravity=196.2;s.cameraForward={1,0,0};s.naturalShape={2,2,3,true};ff3qb::BallFlight b;b.id=100;b.thrower=99;b.at=10;b.airborne=true;b.radius=.5;b.position={30,7,0};b.velocity={-60,0,0};b.gravity=28;s.balls={b};
 InterceptionConfig c;auto began=now();double worst=0;unsigned jumps=0,dives=0,runs=0,reachable=0;
 for(double x:{12.,30.,40.,60.})for(double y:{5.,9.,14.,18.}){auto scene=s;scene.balls[0].position={x,y,0};const double at=now();auto p=buildInterception({scene,{},c,10});worst=std::max(worst,now()-at);check(p.valid&&p.ball==100&&p.contactAt>10&&p.pid==1&&p.own==3,"interception results retain scene identity and a future absolute contact");if(!p.valid)continue;const auto actual=ff3Play::ballAt(scene.balls[0],p.contactAt-10);check(ff3qb::length(actual-p.contact)<.00001,"planned contact lies on the observed flight rather than its landing marker");if(p.reachable){++reachable;check(p.margin>=.12&&p.miss==0,"reachable plans have a positive three-dimensional contact margin");}else check(p.miss>0,"impossible attempts report their miss distance");if(p.action==InterceptionAction::Jump||p.action==InterceptionAction::JumpDive){++jumps;check(p.jumpAt>=10+c.reaction&&p.jumpAt<p.contactAt,"jump launch precedes contact and respects reaction time");}if(p.action==InterceptionAction::Dive||p.action==InterceptionAction::JumpDive){++dives;check(p.diveAt<p.contactAt&&p.diveAt>=10+c.reaction,"dive launch is separately timed before contact");}if(p.action==InterceptionAction::Run)++runs;}
 check(jumps>0&&dives>0&&runs>0&&reachable>0,"the solver selects run, jump and dive opportunities rather than always marking landing");auto p=buildInterception({s,{},c,10});check(p.reachable&&p.contactAt<10.6&&distance(p.contact,p.landing)>5,"a comeback pass is intercepted before its landing location");
 bool boostHelped=false;for(double x:{40.,48.,56.,64.}){auto longPass=s;longPass.balls[0].position={x,14,0};longPass.balls[0].velocity={-60,0,0};auto normal=buildInterception({longPass,{},c,10});auto boosted=c;boosted.boost=boosted.smart=true;boosted.boostDistance=12;auto extra=buildInterception({longPass,{},boosted,10});if(normal.valid&&extra.valid&&extra.reachable&&(extra.contactAt<normal.contactAt-.01||!normal.reachable))boostHelped=true;}check(boostHelped,"interception planning includes the actual optional forward boost budget");
 auto unreachable=s;unreachable.speed=0;unreachable.jumpVelocity=0;unreachable.balls[0].position={120,90,0};unreachable.balls[0].velocity={};auto miss=buildInterception({unreachable,{},c,10});check(miss.valid&&!miss.reachable&&miss.miss>0,"an unreachable high pass cannot be labeled a valid catch");
 auto two=s;auto other=b;other.id=200;other.position={120,20,0};two.balls.push_back(other);check(buildInterception({two,{},c,10}).ball==100,"the closest eligible incoming ball is selected");two.balls[0].thrower=two.player;check(buildInterception({two,{},c,10}).ball==200,"the player's own outgoing ball is excluded");
 auto future=s;future.grounded=false;future.rootPosition.y=7;future.head.y=8.5;future.velocity.y=20;for(const auto& schedule:interceptionSchedules(future,.5,c))check(!std::isfinite(schedule.jump)||schedule.jump>=reachLandingTime(future)+c.reaction,"airborne planning cannot invent a second jump before landing");
 auto fresh=s;fresh.at=10.02;fresh.balls[0]=interceptAligned(b,10.02);auto retained=buildInterception({fresh,{},c,10.02},&p);check(retained.valid&&std::abs(retained.contactAt-p.contactAt)<.05,"a still-reachable contact keeps its absolute timing through replanning");
 Actor rival;rival.id=900;rival.position={12,3.5,0};rival.speed=22;rival.jumpVelocity=50;auto race=buildInterception({s,{rival},c,10});check(race.raceKnown&&std::isfinite(race.rivalAt),"nearby observed players contribute estimated earliest contact times");
 for(int i=0;i<7;++i){auto bad=s;if(i==0)bad.focused=false;if(i==1)bad.typing=true;if(i==2)bad.possessed=true;if(i==3)bad.at=9;if(i==4)bad.groundY=NAN;if(i==5)bad.balls[0].thrower=bad.player;if(i==6)bad.balls[0].at=9;check(!buildInterception({bad,{},c,10}).valid,"stale, own-flight, paused and invalid scenes cannot generate advice");}
 auto raw=s;raw.balls.clear();raw.looseBalls={{701,{2,10,0},{0,0,0},28,false,99,true}};check(buildInterception({raw,{},c,10}).valid,"verified raw flight supports a guide before trajectory fitting");raw.looseBalls[0].verifiedBall=false;check(!buildInterception({raw,{},c,10}).valid,"unverified objects cannot supply catch advice");raw.looseBalls[0].verifiedBall=true;raw.looseBalls[0].position={2,.6,0};check(!buildInterception({raw,{},c,10}).valid,"a resting floor ball cannot masquerade as an incoming pass");
 InterceptionService service;service.submit({s,{},c,10});const double deadline=now()+2;InterceptionPlan async;while(now()<deadline){async=service.snapshot();if(async.valid)break;Sleep(2);}check(async.valid,"the independent planning worker returns a usable plan");service.clear();Sleep(5);check(!service.snapshot().valid,"clearing the guide invalidates pending worker generations");
 std::cout<<"Interception batch "<<(now()-began)*1000<<"ms, slowest solve "<<worst*1000<<"ms (background worker in app)\n";
}
